begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('10000000-0000-0000-0000-000000000098','habit-link-other@memotrail.local');
insert into public.entries(id,owner_id,title,body) values
('96000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Habit link 你好','Original writing'),
('96000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000098','Habit link foreign','Private writing');
insert into public.habits(id,owner_id,name,starts_on) values('96000000-0000-4000-8000-000000000003','10000000-0000-0000-0000-000000000001','Reading','2024-01-01');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is(count(*),1::bigint,'New check-in links the owned Entry atomically') from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-03','completed',null,'First note','96000000-0000-4000-8000-000000000001',null);
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','你好')->>'total_count','1','Chinese search resolves original writing');
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','foreign')->>'total_count','0','Foreign writing is excluded');
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03')->'selected'->>'id','96000000-0000-4000-8000-000000000001','Existing link resolves by exact ID');
select is(count(*),1::bigint,'Legacy client without a link control can update notes') from public.record_habit_occurrence('96000000-0000-4000-8000-000000000003','2024-03-03','completed',null,'Legacy note',null,1);
select is(entry_id,'96000000-0000-4000-8000-000000000001'::uuid,'Legacy null does not erase an existing link') from public.habit_occurrences where habit_id='96000000-0000-4000-8000-000000000003';
update public.entries set deleted_at=now() where id='96000000-0000-4000-8000-000000000001';
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','你好')->>'total_count','0','Trash is excluded from new choices');
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03')->'selected'->>'is_deleted','true','Existing Trash link is explicitly identified');
select is(count(*),1::bigint,'Unchanged owned Trash link survives ordinary edit') from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-03','skipped',null,'Keep link','96000000-0000-4000-8000-000000000001',2);
select is(count(*),0::bigint,'Stale edit does not overwrite current check-in') from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-03','completed',null,'Stale',null,2);
select is(count(*),1::bigint,'Versioned null explicitly unlinks') from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-03','skipped',null,'Unlinked',null,3);
select is(entry_id,null::uuid,'Explicit unlink is persisted') from public.habit_occurrences where habit_id='96000000-0000-4000-8000-000000000003';
select is(snapshot->>'entry_id','96000000-0000-4000-8000-000000000001','Unlink archives the prior relationship') from public.habit_occurrence_versions where habit_id='96000000-0000-4000-8000-000000000003' and version=3;
select throws_ok($$select * from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-04','completed',null,null,'96000000-0000-4000-8000-000000000001',null)$$,'22023','linked_entry_unavailable','New link to Trash denied');
select throws_ok($$select * from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-04','completed',null,null,'96000000-0000-4000-8000-000000000002',null)$$,'22023','linked_entry_unavailable','Known foreign Entry ID denied');
select is(body,'Original writing','Link edits do not rewrite the original Entry') from public.entries where id='96000000-0000-4000-8000-000000000001';
select throws_ok($$select public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03',repeat('a',201))$$,'22023','invalid_habit_entry_page','Long queries rejected');
select throws_ok($$select public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','',-1)$$,'22023','invalid_habit_entry_page','Negative pagination rejected');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000098',true);
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03'),null::jsonb,'Known foreign Habit cannot reveal selected or candidate content');
select throws_ok($$select * from public.save_habit_check_in('96000000-0000-4000-8000-000000000003','2024-03-04','completed',null,null,null,null)$$,'22023','habit_unavailable','Foreign Habit mutation denied');
reset role;
insert into public.entries(owner_id,title,body) select '10000000-0000-0000-0000-000000000001','Habit paging '||lpad(i::text,3,'0'),repeat('x',200) from generate_series(1,25)i;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is(jsonb_array_length(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','Habit paging')->'items'),20,'Candidate pages are bounded');
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','Habit paging')->>'total_count','25','Count includes later pages');
select is(jsonb_array_length(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','Habit paging',20)->'items'),5,'Later candidates remain reachable');
select is(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','Habit paging',20)->'items'->0->>'title','Habit paging 021','Serialized pages retain deterministic ordering');
select is(length(public.habit_entry_choices('96000000-0000-4000-8000-000000000003','2024-03-03','Habit paging')->'items'->0->>'excerpt'),160,'Excerpts are bounded');
reset role;
select ok(not has_function_privilege('anon','public.habit_entry_choices(uuid,date,text,integer)','execute'),'Anonymous candidate access denied');
select ok(not has_function_privilege('anon','public.save_habit_check_in(uuid,date,text,numeric,text,uuid,integer)','execute'),'Anonymous mutation denied');
select * from finish();
rollback;
